#include <iostream>

struct Vec {
    double x = 0, y = 0;
    Vec& operator+=(const Vec& o) { x += o.x; y += o.y; return *this; }
};

Vec operator+(Vec a, const Vec& b) {   // 非成员；传值获得副本，复用 +=
    a += b;
    return a;
}

int main() {
    Vec p{1, 2}, q{10, 20};
    Vec r = p + q;
    std::cout << r.x << ',' << r.y;
}
